 function fail(error){if(!loadActive())return;if(loader)loader.fail(loadAttempt,'研究数据未加载或未通过完整性检查：'+error.message);else {by('np-loading').textContent='研究数据未加载或未通过完整性检查：'+error.message+'。已审静态内容保持可用。';app.setAttribute('data-error','true');}}
 if(!/^[a-f0-9]{64}$/.test(expected)||url!=='product-data.json'){fail(new Error('数据版本配置无效'));return;}
 function cancelled(event){if(event.detail&&event.detail.attempt===loadAttempt&&controller)controller.abort();}
